//go:build ignore

// Copy into upstream converter/xlsx and run TestCodexXLSXDates.
package xlsx
import("encoding/json";"fmt";"math/rand";"os";"path/filepath";"testing")
func TestCodexXLSXDates(t *testing.T){root:=os.Getenv("BDF_FIXTURE_ROOT");if root==""{t.Fatal("BDF_FIXTURE_ROOT required")};r:=rand.New(rand.NewSource(591499));samples:=[]string{"", "1900-01-01", "1900-02-28", "1900-03-01", "1904-01-01", "2024-02-29", "2023-02-29", "9999-12-31", "0000-01-01", "23:59:59", "12:00:00.123", "2024-05-03T12:34:56.123456789Z", "2024-05-03T12:34:56+09:00", "1900-02-29", "2024-01-01T00:00:00,5", "2024-01-01T00:00:00+24:60", "2024-01-01T00:00:00.", "2024-01-01T00:00:00Z", "2024-01-01T", "2024-01-01 ", "01:02:03Z", "01:02:03.12", "2024-02-29T23:59:59.0000000009", "0000-01-01T00:00:00-24:00"};for i:=0;i<10000;i++ {year:=1700+r.Intn(500);m:=1+r.Intn(14);d:=1+r.Intn(34);h:=r.Intn(27);mi:=r.Intn(63);sec:=r.Intn(62);s:=fmt.Sprintf("%04d-%02d-%02dT%02d:%02d:%02d",year,m,d,h,mi,sec);switch r.Intn(5){case 0:s+=fmt.Sprintf(".%09d",r.Intn(1000000000));case 1:s+="Z";case 2:s+=fmt.Sprintf("%+03d:%02d",r.Intn(27)-13,r.Intn(61));case 3:s=s[:10]};samples=append(samples,s)};out:=[]any{};for _,s:=range samples{for _,is1904:=range []bool{false,true}{n,ok:=isoSerial(s,is1904);out=append(out,map[string]any{"input":s,"date1904":is1904,"want":[]any{n,ok}})}};b,e:=json.Marshal(out);if e!=nil{t.Fatal(e)};if e=os.WriteFile(filepath.Join(root,"compat/xlsx/dates.json"),b,0644);e!=nil{t.Fatal(e)}}
